#!/usr/bin/env bash
# Verify a project generated by fastproject.py.
# Usage: verify.sh <project_dir>
set -o errexit
set -o pipefail
set -o nounset

PROJECT_DIR="${1:?usage: verify.sh <project_dir>}"
cd "${PROJECT_DIR}"
unset VIRTUAL_ENV

COMPOSE=(docker compose -f docker-compose.test.yml)
RESULTS=()

step() {
    echo
    echo "=== [verify] $1"
}

cleanup() {
    "${COMPOSE[@]}" down -v --remove-orphans >/dev/null 2>&1 || true
}
trap cleanup EXIT

step "uv.lock matches pyproject.toml"
uv lock --check
RESULTS+=("uv lock --check: ok")

step "prek (all hooks)"
uvx prek==0.5.5 run --all-files
RESULTS+=("prek run --all-files: ok")

step "build test image"
"${COMPOSE[@]}" build
RESULTS+=("docker compose test build: ok")

step "no missing migrations"
"${COMPOSE[@]}" run --rm django python manage.py makemigrations --check --dry-run
RESULTS+=("makemigrations --check: ok")

step "pytest"
"${COMPOSE[@]}" run --rm django pytest
RESULTS+=("pytest: ok")

step "production settings: manage.py check --deploy"
"${COMPOSE[@]}" run --rm \
    -e DJANGO_SETTINGS_MODULE=config.settings.production \
    -e DJANGO_SECRET_KEY="verify-$(date +%s)-not-a-real-secret-key-just-long-enough-for-check" \
    -e DJANGO_ADMIN_URL=admin/ \
    -e DJANGO_ALLOWED_HOSTS=example.com \
    -e DJANGO_SECURE_SSL_REDIRECT=True \
    -e MAILGUN_API_KEY=dummy -e MAILGUN_DOMAIN=example.com \
    -e SENDGRID_API_KEY=dummy -e MAILJET_API_KEY=dummy -e MAILJET_SECRET_KEY=dummy \
    -e MANDRILL_API_KEY=dummy -e POSTMARK_SERVER_TOKEN=dummy -e SENDINBLUE_API_KEY=dummy -e BREVO_API_KEY=dummy \
    -e SPARKPOST_API_KEY=dummy -e SENTRY_DSN= \
    django python manage.py check --deploy --fail-level ERROR
RESULTS+=("check --deploy (production settings): ok")

echo
echo "=== [verify] summary"
printf '  %s\n' "${RESULTS[@]}"
